/**
 * Shapes of the public catalog generated by scripts/build-catalog.mjs.
 *
 * The fields map one-to-one onto a WooCommerce product so the same data feeds
 * the site and data/woocommerce-products.csv: sku, slug, name, short and long
 * description, category (with its parent group), tags (keywords), images
 * (featured first, then gallery), a "Unit" attribute with one variation per
 * unit of sale, stock status and a purchasable flag.
 *
 * Prices are deliberately NOT part of these types. They live in
 * prices.generated.ts and are read only through pricing.ts, behind the switch
 * in lib/storefront.ts.
 */

export type StockStatus = "instock" | "outofstock";

export interface CatalogImage {
  /** Site-relative path under /public/catalog. Always self-hosted. */
  src: string;
  width: number;
  height: number;
  bytes: number;
  alt: string;
  /** "studio" render, "in-use" example scene, or (absent) a photo from the yard. */
  kind?: "studio" | "in-use";
}

export interface CatalogVariation {
  /** The variation's own SKU; equals the product SKU when there is one unit. */
  sku: string;
  unit: string;
  unitPlural: string;
  /** Share of the base unit (0.5 for a half cubic yard). */
  factor: number;
}

export interface CatalogProduct {
  sku: string;
  slug: string;
  name: string;
  categorySlug: string;
  /** The plain search phrase for this kind of product ("bark mulch"). */
  keyword: string;
  /** Completes "<name> is ..." ("a bark mulch"). */
  what: string;
  shortDescription: string;
  /** Long description, one paragraph per entry. */
  description: string[];
  uses: string[];
  /** The sheet's own description, cleaned, when it adds to the name. */
  listingNote: string;
  /** The base unit of sale ("Cubic Yard", "Each", "Pound", ...). */
  unit: string;
  unitPlural: string;
  /** Every unit the product is sold in, the base unit first. */
  variations: CatalogVariation[];
  soldByCubicYard: boolean;
  isService: boolean;
  stockStatus: StockStatus;
  purchasable: boolean;
  /** Featured photo first, then the gallery. Empty when there is no photo yet. */
  images: CatalogImage[];
  /** Generic category image used while a product has no photo. */
  placeholder: string;
  keywords: string[];
  /** Last change in the POS, YYYY-MM-DD. */
  updatedAt: string;
  /**
   * Bay Area demand rank from the POS asset manifest (1 = most in demand), a
   * market proxy rather than recorded sales. Orders the catalog; absent for
   * products the manifest does not rank.
   */
  rank?: number;
  /** "core" marks the everyday materials the yard is known for. */
  tier?: "core" | "standard" | "select";
}

export interface CatalogCategory {
  slug: string;
  name: string;
  /** Parent group in the WooCommerce hierarchy; empty for a top-level category. */
  group: string;
  keyword: string;
  intro: string;
  about: string[];
  placeholder: string;
}
